use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: resize <input> [--width N]");
        process::exit(2);
    }
    let input = &args[1];
    let mut width = 800;
    if args.len() > 3 && args[2] == "--width" {
        width = args[3].parse().unwrap();
    }
    resize(input, width);
}

fn resize(input: &str, width: u32) {
    println!("resizing {input} to {width}px");
}

