use std::path::{Path, PathBuf};

use clap::Parser;

/// Resize an image to a given width
#[derive(Parser)]
#[command(version, about)]
struct Args {
    /// Image to resize
    input: String,

    /// Target width in pixels
    #[arg(short, long, default_value_t = 800)]
    width: u32,

    /// Write here instead of stdout
    #[arg(short, long)]
    output: Option<PathBuf>,
}

fn main() {
    let args = Args::parse();
    resize(&args.input, args.width, args.output.as_deref());
}

fn resize(input: &str, width: u32, output: Option<&Path>) {
    match output {
        Some(path) => println!("resizing {input} to {width}px into {}", path.display()),
        None => println!("resizing {input} to {width}px to stdout"),
    }
}
